WITH unpivoted AS (SELECT * FROM (SELECT id, store_id, amount, discount, shipping_fee FROM orders) src UNPIVOT INCLUDE NULLS (reading FOR metric_name IN (amount AS AMOUNT_VAL, discount, shipping_fee))) SELECT CASE WHEN reading >= 69 THEN 'PREMIUM' ELSE 'STANDARD' END AS reading_tier, metric_name, ROUND(AVG(reading), 2) AS avg_reading, ROUND(SUM(reading) / NULLIF(COUNT(CASE WHEN metric_name = 'shipping_fee' THEN 1 END), 0), 2) AS reading_per_shipping_fee, COUNT_IF(metric_name = 'discount') AS discount_events FROM unpivoted GROUP BY CUBE (CASE WHEN reading >= 69 THEN 'PREMIUM' ELSE 'STANDARD' END, metric_name)
